  const pin=snapshot.binding;
  if(cursor && (Object.keys(cursor).sort().join("|")!=="categoryId|family|lastId|namespace|pointerVersion|policyHash|policyRevision|profileScope|releaseId|releaseRoot" || cursor.namespace!==claims.namespace || cursor.family!=="published-questions" || cursor.policyRevision!==claims.policyRevision || cursor.policyHash!==claims.policyHash || cursor.profileScope!==pin.profileScope || cursor.pointerVersion!==pin.pointerVersion || cursor.releaseId!==pin.releaseId || cursor.releaseRoot!==pin.releaseRoot || cursor.categoryId!==categoryId || !snapshot.questions.has(cursor.lastId) || snapshot.questions.get(cursor.lastId)?.categoryId!==categoryId)) throw new Error("STALE_CURSOR");
