 if(Object.keys(patch).some(k=>!allowed.includes(k))) throw new Error("INVALID_REQUEST");
 for(const k of ["maintenanceMode","roomCreationEnabled"]) if(k in patch && typeof patch[k]!=="boolean") throw new Error("INVALID_REQUEST");
 if("maintenanceMessageAr" in patch && (typeof patch.maintenanceMessageAr!=="string" || patch.maintenanceMessageAr.length>500)) throw new Error("INVALID_REQUEST");
 for(const [key,min,max] of [["defaultQuestionTimerSeconds",5,600],["defaultOpponentTimerSeconds",3,300],["roomRetentionDays",1,365]] as const) if(key in patch && (!Number.isSafeInteger(patch[key]) || (patch[key] as number)<min || (patch[key] as number)>max)) throw new Error("INVALID_REQUEST");
