export interface RegistryDependencies { resolveIdentity(projectId:string,uid:string):Promise<string|null>; sync?:{auth:SyncAuthIo;settlement:SyncSettlementVerifier;completion:SyncCompletionIo} }
/** Registry commit is durable before any effect; replay never redispatches. */
