export interface QuestionDraft {categoryId:string;modality:"classic"|"image"|"charades";headerAr:string;promptAr:string;canonicalAnswer:string;acceptedAnswers:string[];specialistRoles:string[];sources:Array<Record<string,unknown>>;status:"draft"|"ready_for_review"}
